#!/usr/bin/env python3
"""Add truthful 0.8.3 preview guidance without changing official release metadata."""
from pathlib import Path
import re
ROOT=Path(__file__).resolve().parents[1]; D=ROOT/'docs'
shell=(D/'index.html').read_text()
head=shell[:shell.index('<main')]
head=re.sub(r'<title>.*?</title>', '<title>MeBot 0.8.3 preview and guide · MeBot</title>',head)
head=re.sub(r'<meta property="og:title" content="[^"]*">', '<meta property="og:title" content="MeBot 0.8.3 preview and guide">', head)
head=head.replace('Explore your interests, read sourced information, ask MeBot and keep useful resources. Download the official Android release.', 'Preview the MeBot 0.8.3 changes, usage guidance and remaining release checks. Official download: 0.8.2.')
head=head.replace('https://emmanuelmmanda.github.io/MeBot/index.html','https://emmanuelmmanda.github.io/MeBot/preview-083.html').replace(' aria-current="page"','')
foot=shell[shell.index('<footer'):]
foot=foot.replace('Native Android host capture with dated public source content and controlled request state.', 'Native Android candidate render with test content and controlled provider state.')
body='''<main id="main"><section class="section wrap preview-intro"><p class="eyebrow">Next Android update · 0.8.3 preview</p><h1>MeBot 0.8.3</h1><p class="lead">Star a story to follow its topic, organize useful reading, and explore links, files and media from your conversation.</p><div class="preview-status"><strong>Preview, not a published APK</strong><p>The 0.8.3 candidate passed 817 automated tests and both APK builds. Physical-device checks remain outstanding. An official update also needs the existing release signing identity. The available official download remains 0.8.2. Do not uninstall your current app or install an unsigned file.</p><div class="actions"><a class="button" href="download.html">Get official 0.8.2</a><a class="button secondary" href="#guide">Explore 0.8.3 changes</a></div></div><nav class="preview-jumps" aria-label="On this page"><a href="#follow">Star &amp; save</a><a href="#conversation">Chat &amp; media</a><a href="#interests">Interests</a><a href="#reading">Reading controls</a><a href="#prices">Compare prices</a><a href="#kiswahili">Kiswahili</a></nav></section>
<section class="section wrap hairline" id="guide"><div class="section-heading"><div><p class="eyebrow">What changes in daily use</p><h2>A guide to the new controls</h2><p>These instructions describe the 0.8.3 candidate. The screenshots elsewhere on this website remain explicitly labelled 0.8.2 until new captures are verified.</p></div></div><div class="preview-guide">
<article id="follow"><span class="preview-number">01</span><div><h3>Star a topic. Save a useful read.</h3><p>Use <strong>Star · follow this</strong> on a story you want MeBot to revisit. In <strong>Saved → Following</strong>, pause follow-ups or choose a 6-hour, daily, 3-day or weekly cadence. Hiding a story pauses its follow-up. Follow-ups use your connected provider and normal request allowance during feed refresh; starring does not promise fresh coverage or immediately spend an extra request.</p><p>Saving keeps the item in <strong>Your library</strong>. Search titles, sources, summaries and collection names; narrow by topic or collection and choose a reading order. Give collections names that suit you, such as Work or Read later. Your saved reads remain available when the feed changes.</p></div></article>
<article id="conversation"><span class="preview-number">02</span><div><h3>Open the resource, not the markup.</h3><p>Recognized links appear with media or document actions. Open a supported video, inspect a source or read a PDF with page controls. A failed preview offers a retry or the original resource rather than blocking the conversation.</p><p>After a question is accepted, the composer clears. Shared files remain visible in that conversation for follow-ups and can be removed. This is not permission for other conversations or modules to use them.</p><p><strong>Voice options:</strong> speak a question, review it, then send. Choose a compatible voice installed on your phone and a reading speed for read-aloud. This is not a full-duplex, always-listening call. ChatGPT sign-in does not automatically include separately billed realtime APIs.</p><p><strong>Browsing:</strong> supported browser-owned tabs keep a route back to MeBot and show the site's identity. Sign-in stays in the provider-supported secure browser flow. MeBot does not replace it with a password-collecting embedded page.</p></div></article>
<article id="interests"><span class="preview-number">03</span><div><h3>Choose interests in ordinary language.</h3><p>Search topics during onboarding or show more choices. New areas include food and cooking, farming and gardening, family life, sports, practical home skills, and rest and wellbeing. Existing preferences remain yours; new topics are not silently enabled on upgrade.</p><p><strong>About you</strong> offers optional prompts for what you enjoy, work and learning, a goal, and how you like information. Start with one useful detail. Choose which topics may use it. A city is optional, and importing a JSON file is never required to begin.</p><p>The Modules screen adds clearer search and category filters. Each topic can have its own focus and permitted personal details.</p></div></article>
<article id="reading"><span class="preview-number">04</span><div><h3>Keep reading without losing your place.</h3><p><strong>Reading &amp; progress</strong> lets you choose whether more stories load as you scroll, and how much observed activity appears. Cached stories appear five at a time. After scrolling, a filter session may request one automatic network batch, with a 60-second throttle and a manual alternative. Loading stays bounded by availability and your request allowance. The app does not invent an endless stream when sources have nothing new.</p><p>New-item controls reveal newly received item identities rather than re-showing the same cards. Progress reports observed stages, received text and results, not fabricated reasoning or a timer pretending to be work.</p><p>Notification images and story-title previews are configurable. Notifications remain optional, respect quiet hours and are limited to a daily digest. Hide titles for a more private lock screen. These settings do not increase your AI allowance.</p></div></article>
<article id="prices"><span class="preview-number">05</span><div><h3>Compare prices, even offline.</h3><p>Enter the price and quantity for two packs. MeBot compares the cost per unit and shows which costs less. Use the same currency and unit for both; convert grams to kilograms yourself before comparing.</p><p>For example, 2 kg at TZS 6,000 costs TZS 3,000 per kg. A 5 kg pack at TZS 14,000 costs TZS 2,800 per kg. The larger pack costs less per kg; quality, delivery and other costs are not included. No AI connection is needed.</p></div></article></div></section>
<section class="section wrap hairline" id="kiswahili" lang="sw"><p class="eyebrow">Mwongozo mfupi</p><h2>MeBot 0.8.3 kwa kifupi</h2><div class="preview-sw"><p><strong>Fuatilia unachopenda.</strong> Weka nyota kwenye habari unayotaka kuifuatilia. Kwenye sehemu ya ulivyohifadhi, unaweza kupanga makundi, kutafuta habari na kusitisha ufuatiliaji. Taarifa mpya hutafutwa wakati wa kusasisha habari, kwa kufuata kikomo chako cha matumizi.</p><p><strong>Uliza, soma na sikiliza.</strong> Viungo vya video na nyaraka vina vitendo vilivyo wazi. Unaweza kusoma PDF au kufungua chanzo. Ukiuliza kwa sauti, kagua swali kabla ya kulituma. Kusoma jibu kwa sauti hutumia sauti iliyosakinishwa kwenye simu; si mazungumzo ya moja kwa moja ya sauti.</p><p><strong>Jiwekee unavyopenda.</strong> Chagua mada zako, kisha ongeza maelezo machache yanayokusaidia kupata taarifa muhimu. Si lazima ujaze kila kitu. Unaweza kubadili chaguo zako baadaye.</p><p><strong>Linganisha bei.</strong> Weka bei na kiasi cha bidhaa mbili ili kuona ipi ina gharama ndogo kwa kipimo kimoja. Tumia sarafu na kipimo kilekile. Zana hii haihitaji intaneti.</p><p><strong>Toleo hili bado linahakikiwa.</strong> Upakuaji rasmi uliopo ni 0.8.2. Usifute programu uliyonayo ili kujaribu faili ambayo haijasainiwa.</p></div></section>
<section class="section wrap hairline" id="verification"><h2>What still needs verification</h2><p>Automated tests and Android host captures do not establish live provider eligibility, physical-phone playback, notification delivery, installation or overnight alarms. Those checks remain separate. Release signing must match the installed official app before an upgrade is offered.</p><div class="actions"><a class="button secondary" href="RELEASE-0.8.3.md">Candidate notes</a><a class="text-link" href="guide.html">Official 0.8.2 guide →</a><a class="text-link" href="https://github.com/EmmanuelMmanda/MeBot">View source →</a></div></section></main>'''
captures = [
    ('feed-stars','Star a story','A starred story and follow-up guidance inside its main card. The story is synthetic test content.'),
    ('rich-chat','Links with useful actions','A recognized video link with preview and original-source controls. The answer and connected-provider state are fixtures.'),
    ('saved-library','Revisit followed stories','The Following tab shows a starred story, a collection and its daily follow-up control. Dated public-source fixture content, not live coverage.'),
    ('module-filters','Find an interest','Search and spaced filters narrow the catalog to Farming & gardening.'),
    ('price-comparison','Compare two prices','Native calculator component with sample values. Option B costs 20% less per unit. This is a component capture, not a complete app screen.')
]
import struct
figures=[]
for name,title,caption in captures:
    source=D/'screenshots/v083'/f'{name}.png'
    if not source.exists(): continue
    width,height=struct.unpack('>II',source.read_bytes()[16:24])
    figures.append(f'<figure class="shot"><a href="screenshots/v083/{name}.png" data-lightbox data-title="{title}" aria-label="Enlarge: {title}"><img src="screenshots/v083/{name}.png" width="{width}" height="{height}" loading="lazy" alt="{caption}"></a><figcaption><span class="shot-version">0.8.3 candidate · native render</span><strong>{title}</strong><span>{caption}</span></figcaption></figure>')
if figures:
    gallery='<section class="section wrap hairline" id="native-preview"><p class="eyebrow">Actual Android candidate</p><h2>See the new controls</h2><p>Rendered from the native Android implementation with synthetic or dated public-source test data and controlled provider state. These images show layout, not live account access, real video playback or physical-phone acceptance.</p><div class="screen-grid">'+''.join(figures)+'</div><p class="micro"><a href="screenshots/v083/README.md">Capture provenance</a></p></section>'
    body=body.replace('<section class="section wrap hairline" id="guide">',gallery+'<section class="section wrap hairline" id="guide">')
    body=body.replace('The screenshots elsewhere on this website remain explicitly labelled 0.8.2 until new captures are verified.', 'The candidate renders above are labelled 0.8.3; the official gallery elsewhere remains labelled 0.8.2.')
(D/'preview-083.html').write_text(head+body+foot)
# Versioned preview links are explicit and survive regeneration. Never alter release.json.
for p in [*D.glob('*.html'), * (D/'guides').glob('*.html')]:
    if p.name=='preview-083.html': continue
    text=p.read_text()
    text=re.sub(r'<!-- preview-083:start -->.*?<!-- preview-083:end -->','',text,flags=re.S)
    rel='../' if p.parent.name=='guides' else ''
    note=f'<!-- preview-083:start --><aside class="preview-banner"><strong>0.8.3 preview</strong> · Starred topics, a richer library and easier everyday tools. <a href="{rel}preview-083.html">See changes and release status →</a></aside><!-- preview-083:end -->'
    text=text.replace('</header>','</header>'+note,1).replace('All guides <small>v0.6.1</small>','All guides <small>Official 0.8.2</small>')
    p.write_text(text)
for path,link in [(ROOT/'README.md','docs/RELEASE-0.8.3.md'),(ROOT/'START-HERE.md','docs/RELEASE-0.8.3.md'),(D/'USER-GUIDE.md','RELEASE-0.8.3.md')]:
    text=path.read_text();text=re.sub(r'<!-- preview-083:start -->.*?<!-- preview-083:end -->\n*','',text,flags=re.S)
    marker=f'<!-- preview-083:start -->\n> **0.8.3 preview:** Starred follow-ups, searchable collections, rich conversation resources, broader interests and an offline price comparison tool. [Candidate guide]({link}). 817 automated tests passed; physical-device verification and original-identity signing remain pending; the official downloadable release remains **0.8.2**.\n<!-- preview-083:end -->\n\n'
    path.write_text(marker+text)
print('Updated 0.8.3 preview and guide links; official 0.8.2 manifest unchanged.')
